export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
  const page = await (await browser.newContext()).newPage();
  await page.goto('/');
  await page.getByTestId('signin-name').fill(user);
  await page.getByTestId('signin-submit').click();
  await expect(page.getByTestId('current-user')).toHaveText(user);
  await loadSheet(page, sheet);
  return page;
}

export async function loadSheet(page: Page, sheet: string): Promise<void> {
  await page.getByTestId('sheet-id-input').fill(sheet);
  await page.getByTestId('sheet-load').click();
  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet);
}

/** Re-load the active sheet so the screen shows what the store holds now. */
export async function refresh(page: Page): Promise<void> {
import { Component, inject, linkedSignal, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { RatesPanel } from '../rates/rates';

// The one screen: sign in by name, then choose a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People, RatesPanel],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set($any($event.target).value); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-error">{{ err }}</p>
        }
      </form>

      @if (session.sheetId(); as id) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ id }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>

        <form (submit)="saveToday($event)">
          <label for="sheet-today">Change today</label>
          <input
            id="sheet-today"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set($any($event.target).value); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Save</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-today-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-people />
      }
    } @else {
      <form (submit)="signIn($event)">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set($any($event.target).value); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = linkedSignal(() => this.session.today() ?? '');
  protected readonly todayError = signal<string | null>(null);

  protected signIn(event: Event): void {
    event.preventDefault();
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter your name.');
      return;
    }
    this.signinError.set(null);
    this.session.signIn(name);
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('The sheet could not be loaded.');
    }
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    this.todayError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.todayError.set('That date could not be saved.');
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  /** The sheet's "today" (yyyy-mm-dd): every date decision and default date uses it. */
  today: string;
}

// The signed-in user (a typed name, no password) and the active sheet. Everything else in the app
// is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's "today" — use this, never the real clock, for dates in the sheet. */
  readonly today = signal<string | null>(null);
  /** Counts sheet loads, so per-sheet data re-reads the store on every (re-)load. */
  readonly loads = signal(0);

  signIn(name: string): void {
    this.user.set(name.trim());
  }

  /** Load (or re-load) a sheet by id; a never-used id starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const sheet = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id.trim())}/load`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.show(sheet);
    this.loads.update((n) => n + 1);
  }

  /** Change the active sheet's "today". */
  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const sheet = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    this.show(sheet);
  }

  private show(sheet: SheetView): void {
    this.sheetId.set(sheet.id);
    this.today.set(sheet.today);
  }
}

